/* Parser tests against real CLI output fixtures (from /tmp/opencode/fixtures,
 * regenerated by npm test). Run: node test/parsers.test.cjs */
const { stripANSI, parseSkillListing, parseFindOutput, tryJSON } = require("../electron/parsers.cjs");
const fs = require("node:fs");
const path = require("node:path");

const FIX = "/tmp/opencode/fixtures";
let failures = 0;

function check(name, cond, extra) {
  if (cond) {
    console.log(`  ✓ ${name}`);
  } else {
    failures++;
    console.error(`  ✗ ${name}`, extra ?? "");
  }
}

/* ---------- add -l listing ---------- */
{
  const raw = fs.readFileSync(path.join(FIX, "list-mattpocock.txt"), "utf8");
  const { skills, found } = parseSkillListing(raw);
  check("listing: found 38 announced in output", /Found 38 skills/.test(raw));
  check("listing: skills parsed", skills.length > 0, `got ${skills.length}`);
  check(
    "listing: has ask-matt with description",
    skills.find((s) => s.name === "ask-matt")?.description?.includes("router over the skills"),
  );
  check(
    "listing: code-review description complete-ish",
    (skills.find((s) => s.name === "code-review")?.description || "").length > 40,
  );
  check(
    "listing: no spinner or ANSI residue in descriptions",
    skills.every((s) => !/[◒◓◐◑▌]/.test((s.description + s.name)) && !/\x1b/.test(s.description + s.name)),
  );
}

/* ---------- find fallback ---------- */
{
  const raw = fs.readFileSync(path.join(FIX, "find-react.txt"), "utf8");
  const items = parseFindOutput(raw);
  check("find: parsed result rows", items.length > 5, `got ${items.length}`);
  const top = items[0];
  check(
    "find: first row is vercel-react-best-practices",
    top?.source === "vercel-labs/agent-skills" && top?.skillId === "vercel-react-best-practices",
    JSON.stringify(top),
  );
  check("find: installs text captured", /^[\d.]+[KM]?$/.test(top?.installsText || ""), top?.installsText);
}

/* ---------- ls --json ---------- */
{
  const sample = JSON.stringify([
    { name: "frontend-design", path: "/x/y", scope: "global", agents: ["OpenCode"], source: "anthropics/skills", sourceUrl: "https://x", sourceType: "github", status: "tracked" },
  ]);
  const parsed = tryJSON(sample);
  check("list json: parses array shape", Array.isArray(parsed) && parsed[0].agents?.length === 1);
}

/* ---------- ANSI stripping edge cases ---------- */
{
  const nasty = "\x1b[?25l│\x1b[1G\x1b[J◒  Discovering skills…\x1b[?25h";
  check("stripANSI: removes cursor+spinner frames", !/x1b|\?\d+[lh]/.test(stripANSI(nasty)));
}

if (failures > 0) {
  console.error(`\n${failures} failing`);
  process.exit(1);
}
console.log("\nall parser tests passed");
